def fp(v):return hashlib.sha256(json.dumps(v,sort_keys=True).encode()).hexdigest()
def arrow(points,s,ox,oy,color,label):
 return line(points,s,ox,oy,color,3,'marker-end="url(#arrow)"')
def door(d,s,ox,oy,short,color='#111827'):
 x,y=d['door_center'];return line(d['door_face'],s,ox,oy,color,5)+mark(x,y,short,s,ox,oy,color)
def base_plan(study,c,ox,oy,s):
 p=study['local_parcel_polygon'];out=[poly(p,s,ox,oy,'#fff','#111827',1,2.5),poly([[p[0][0],-2],[p[1][0],-2],[p[1][0],0],[p[0][0],0]],s,ox,oy,'#cbd5e1','#64748b')]
 out += [text(ox,oy+42,'SOUTH — 10 m ROAD',12,'#334155','bold'),text(ox,oy-20*s,'NORTH PRIVATE — NO OPENING',10,'#b91c1c','bold'),text(ox-26,oy-9*s,'WEST — NO OPENING',10,'#b91c1c','bold')]
 for i,u in enumerate(c['unit_envelopes']):out.append(poly(u['polygon'],s,ox,oy,['#bfe3b5','#b7d7f0'][i],['#39833d','#17658a'][i],.68,2))
 court=c['shared_daylight_court'];out += [poly(court['court_polygon'],s,ox,oy,'#d9f4ff','#0284c7',.9,2.5),poly(c['common_lobby_polygon'],s,ox,oy,'#f5dda8','#9a6b12',.9),poly(c['stair']['landing_geometry'],s,ox,oy,'#c4a7e7','#70408c',.9),poly(c['elevator']['polygon'],s,ox,oy,'#f3c2d1','#9d3155',.9),poly(c['elevator']['elevator_front_clear_zone'],s,ox,oy,'#ffe8a3','#d97706',.55)]
 for t in c['terraces']:out.append(poly(t['terrace_polygon'],s,ox,oy,'#80cbc4','#00796b',.9,2))
 g=c['residential_common_access_graph'];colors={'stair_to_unit_1':'#16803a','stair_to_unit_2':'#2563eb','elevator_to_unit_1':'#7e22ce','elevator_to_unit_2':'#ea580c','common_to_court_maintenance':'#7c4a2d'}
 labels={'stair_to_unit_1':'STAIR→U1','stair_to_unit_2':'STAIR→U2','elevator_to_unit_1':'ELEV→U1','elevator_to_unit_2':'ELEV→U2','common_to_court_maintenance':'COMMON→COURT'}
 for k,path in g['walk_path_proofs'].items():out.append(arrow(path,s,ox,oy,colors[k],labels[k]))
 for i,d in enumerate(g['unit_entry_doors']):out.append(door(d,s,ox,oy,f'D{i+1}'))
 out.append(door(c['maintenance_door'],s,ox,oy,'DM','#7c4a2d'))
 out += [line(c['elevator']['elevator_door_face'],s,ox,oy,'#9d3155',5),mark(*c['stair']['stair_start_point'],'STAIR START / UP',s,ox,oy,'#6b21a8'),mark(*c['stair']['stair_end_point'],'STAIR END / EXIT',s,ox,oy,'#6b21a8')]
 if c['projection_mode'].endswith('enabled'):
  x0=min(x for x,y in p);x1=max(x for x,y in p);out += [line([[x0,-.8],[x1,-.8]],s,ox,oy,'#c026d3',3,'stroke-dasharray="8 5"'),text(ox,oy+70,'0.80 m CANDIDATE — MINAB LOCAL APPROVAL PENDING',11,'#c026d3','bold')]
 return out
def plan_svg(study,c):
 defs='<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="context-stroke"/></marker></defs>';out=['<svg xmlns="http://www.w3.org/2000/svg" width="1550" height="980"><rect width="100%" height="100%" fill="#f7f8f6"/>',defs]+base_plan(study,c,75,800,33);court=c['shared_daylight_court'];proj=c['projection_opportunity']['public_road_projection'];rows=[c['candidate_id'],f'COURT U1/U2 edges {court["unit_1_daylight_edge_length"]:.1f}/{court["unit_2_daylight_edge_length"]:.1f} m | balance {court["daylight_balance_ratio"]:.2f}',f'Maintenance {c["shared_daylight_court_maintenance_access"]["maintenance_path_length"]:.1f} m / COMMON',f'Access graph {c["residential_common_access_graph"]["graph_status"]}',f'Privacy {c["shared_court_privacy_topology"]["privacy_status"]}',f'Projection {proj["projection_status"]}',f'Height check {proj.get("projection_geometry_status","not_applicable")}',f'Penalties: {", ".join(c["architectural_quality_penalties"]) or "none"}','NO ROOMS / NO FINAL WINDOWS / NO WINNER']
 for i,r in enumerate(rows):out.append(text(520,55+i*31,r,20 if i==0 else 14,'#b91c1c' if i in (5,6) else '#17212b','bold' if i in (0,8) else 'normal'))
 out += [text(520,390,'GREEN ARROW stair→D1 | BLUE ARROW stair→D2',14),text(520,420,'PURPLE ARROW elevator→D1 | ORANGE ARROW elevator→D2',14),text(520,450,'BROWN ARROW lobby→DM→court | D1/D2 unit doors | DM maintenance',14),text(520,480,'MAGENTA dashed = conditional projection opportunity',14),'</svg>'];return ''.join(out)
def access_graph_svg(c):
 g=c['residential_common_access_graph'];nodes={n['node_id']:n for n in g['nodes']};xmap={'stair_start':80,'stair_end':220,'stair_landing':360,'elevator_door':80,'elevator_front':260,'common_lobby':560,'common_corridor_junction':700,'unit_1_door':970,'unit_2_door':970,'daylight_court_maintenance_door':970};ymap={'stair_start':170,'stair_end':170,'stair_landing':170,'elevator_door':390,'elevator_front':390,'common_lobby':280,'common_corridor_junction':280,'unit_1_door':120,'unit_2_door':280,'daylight_court_maintenance_door':450};out=['<svg xmlns="http://www.w3.org/2000/svg" width="1250" height="650"><rect width="100%" height="100%" fill="#fafafa"/>',text(35,38,f'{c["candidate_id"]} — RESIDENTIAL COMMON ACCESS GRAPH',22,'#17212b','bold')]
 for e in g['edges']:
  a,b=e['start_node'],e['end_node'];out.append(f'<line x1="{xmap[a]}" y1="{ymap[a]}" x2="{xmap[b]}" y2="{ymap[b]}" stroke="#16803a" stroke-width="4"/>');out.append(text((xmap[a]+xmap[b])/2,(ymap[a]+ymap[b])/2-7,f'{e["path_length"]:.1f}m',10))
 for n in nodes:out += [f'<circle cx="{xmap[n]}" cy="{ymap[n]}" r="12" fill="#f5dda8" stroke="#7c5b12" stroke-width="2"/>',text(xmap[n]-35,ymap[n]+30,n,11,'#17212b','bold')]
 out += [text(35,570,f'Graph status: {g["graph_status"]} | Common until threshold: {g["paths_stay_common_until_unit_threshold"]}',15,'#17212b','bold'),'</svg>'];return ''.join(out)
