def comparison(study):
 picks=[next(c for c in study['human_review_candidates'] if c['split_family']==f and c['projection_mode']=='projection_disabled') for f in ('R-EW','R-NS','R-HYBRID')];defs='<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="context-stroke"/></marker></defs>';out=['<svg xmlns="http://www.w3.org/2000/svg" width="1800" height="980"><rect width="100%" height="100%" fill="#f7f8f6"/>',defs,text(35,38,'REAL PARCEL 2 — SHARED COURT / COMMON ACCESS COMPARISON',23,'#17212b','bold')]
 for i,c in enumerate(picks):
  ox=35+i*585;out+=base_plan(study,c,ox,520,20);court=c['shared_daylight_court'];out += [text(ox,590,c['candidate_id'],15,'#17212b','bold'),text(ox,615,f'Court edges U1/U2 {court["unit_1_daylight_edge_length"]:.1f}/{court["unit_2_daylight_edge_length"]:.1f} m | balance {court["daylight_balance_ratio"]:.2f}',12),text(ox,640,f'Access {c["residential_common_access_graph"]["graph_status"]} | Maintenance COMMON',12),text(ox,665,f'Privacy {c["shared_court_privacy_topology"]["privacy_status"]}',11)]
 out += [text(35,820,'Every family retains a no-projection fallback. Projection variants remain conditional and unapproved.',14,'#9a3412','bold'),text(35,850,'No final residential topology selected.',16,'#17212b','bold'),'</svg>'];return ''.join(out)
def png(svg,pngfile,profile,width):
 chrome=Path(r'C:\Program Files\Google\Chrome\Application\chrome.exe')
 if chrome.exists():subprocess.run([str(chrome),'--headless','--no-sandbox','--disable-gpu',f'--user-data-dir={profile}','--hide-scrollbars',f'--window-size={width},980',f'--screenshot={pngfile}',svg.as_uri()],check=True)
def main():
 bp=sorted((ROOT/'exports'/'DEFAULT').glob('parcel2_basement_v2_*/PARCEL2_BASEMENT_V2_CONTRACT.json'))[-1];root=bp.parent;b=json.loads(bp.read_text());a=json.loads(sorted(root.glob('program_alternative_recommendation_v1_*/PARCEL2_PROGRAM_ALTERNATIVE_RECOMMENDATION_V1.json'))[-1].read_text())['baseline_scenario_a'];pilot=json.loads(sorted(root.glob('program_driven_pilot_space_composition_v1_*/PROGRAM-A_CONTRACT.json'))[-1].read_text())['human_review_candidates'][0];before=fp((b,a,pilot));r=ResidentialFloorAccessDaylightTopologyV2().resolve(b['site'],a,pilot,{'jurisdiction':'Minab','allowed_floor_count':5},{'allow_public_road_projection':True});assert before==fp((b,a,pilot));folder=root/('residential_access_daylight_topology_v2_'+datetime.now().strftime('%Y%m%d_%H%M%S'));folder.mkdir();contract=folder/'PARCEL2_RESIDENTIAL_ACCESS_DAYLIGHT_TOPOLOGY_V2.json';contract.write_text(json.dumps(r,indent=2,ensure_ascii=False),encoding='utf-8');outputs=[]
 for c in r['human_review_candidates']:
  svg=folder/f'{c["candidate_id"]}.svg';preview=svg.with_suffix('.png');svg.write_text(plan_svg(r,c),encoding='utf-8');png(svg,preview,folder/f'.chrome_{c["candidate_id"]}',1550);outputs.append(str(svg))
 primary=next(c for c in r['human_review_candidates'] if c['split_family']=='R-NS' and c['projection_mode']=='projection_disabled');access=folder/'PARCEL2_RESIDENTIAL_COMMON_ACCESS_GRAPH.svg';access.write_text(access_graph_svg(primary),encoding='utf-8');ap=access.with_suffix('.png');png(access,ap,folder/'.chrome_access',1250);section=folder/'PARCEL2_DAYLIGHT_COURT_PROJECTION_SECTION.svg';section.write_text(section_svg(r,next(c for c in r['human_review_candidates'] if c['projection_mode'].endswith('enabled'))),encoding='utf-8');sp=section.with_suffix('.png');png(section,sp,folder/'.chrome_section',1400);comp=folder/'PARCEL2_RESIDENTIAL_SHARED_COURT_COMPARISON.svg';comp.write_text(comparison(r),encoding='utf-8');cp=comp.with_suffix('.png');png(comp,cp,folder/'.chrome_comparison',1800);print(json.dumps({'contract':str(contract),'candidate_count':r['candidate_count'],'hard_valid':r['hard_valid_candidate_count'],'plans':outputs,'access_graph':str(access),'section':str(section),'comparison':str(comp),'final_selection_performed':False,'program_changed':False,'basement_deleted':False}))
if __name__=='__main__':main()
